  // ---------- tips ----------
  "Show tips": "Показывать подсказки",
  "Short tips the first time you open a model or board, measure or add a section": "Короткие подсказки при первом открытии модели или платы, первом измерении или сечении",
  "Got it": "Понятно",
  "Turn off tips": "Отключить подсказки",
  "Tip: click a face, edge or hole to measure it; click a second one for the distance, pitch or angle between them. Right-drag pans, the wheel zooms.": "Подсказка: щёлкните грань, ребро или отверстие, чтобы измерить его; щелчок по второму даёт расстояние, шаг или угол между ними. Правая кнопка сдвигает, колесо масштабирует.",
  "Tip: click a value in the result card to copy it. 📌 Pin keeps the result in the Measurements list; Esc clears it.": "Подсказка: щёлкните значение в карточке результата, чтобы скопировать его. 📌 Закрепить сохраняет результат в списке измерений; Esc сбрасывает.",
  "Tip: for two holes, switch between centre to centre, minimum and maximum in the result card.": "Подсказка: для двух отверстий в карточке результата можно переключить центр–центр, минимум и максимум.",
  "Tip: drag either arrow on the plane, or type an offset, to move the cut. The cut curves can be snapped to for measuring.": "Подсказка: тяните любую из стрелок на плоскости или введите смещение, чтобы сдвинуть разрез. К линиям разреза можно привязываться при измерениях.",
  "Tip: click a pad, track or hole for its size; a second click gives pitch and clearance. Shift+click a shape for its area, 3 shows the board in 3D.": "Подсказка: щёлкните площадку, дорожку или отверстие, чтобы узнать размер; второй щелчок даёт шаг и зазор. Shift+щелчок по фигуре даёт её площадь, клавиша 3 показывает плату в 3D.",
  "Tip: in 3D, drag orbits and right-drag pans; measuring works on the side you look at. B turns the board over.": "Подсказка: в 3D перетаскивание вращает, правой кнопкой — сдвиг; измерения работают на видимой стороне. B переворачивает плату.",
  "Tip: type size>50 or vol<1000 in the filter to find large or small parts. Double-click a part to zoom to it.": "Подсказка: введите в фильтр size>50 или vol<1000, чтобы найти большие или маленькие детали. Двойной щелчок приближает к детали.",

  // ---------- 1.13: exact geometry, STEP / DXF export, notes, mesh files ----------
  "Open STEP / IGES / BREP, STL / OBJ / 3MF, or Gerber / Excellon layers and .zip sets (Ctrl+O)": "Открыть STEP / IGES / BREP, STL / OBJ / 3MF или слои Gerber / Excellon и наборы .zip (Ctrl+O)",
  "AP203 · AP214 · AP242, plus IGES, BREP and SolidWorks parts and assemblies, parsed by OpenCASCADE, and STL, OBJ and 3MF meshes. PCB layers: Gerber RS-274X / X2, Excellon drill and .zip sets. Everything runs in your browser: files never leave your computer.": "AP203 · AP214 · AP242, а также IGES, BREP и детали и сборки SolidWorks, разбор с помощью OpenCASCADE, и сетки STL, OBJ и 3MF. Слои плат: Gerber RS-274X / X2, сверловка Excellon и наборы .zip. Всё работает в браузере: файлы не покидают ваш компьютер.",
