  "One row per segment: its end time after the motor start (s), its end value ({u}) and its shape: linear, cubic, quintic, harmonic or cycloid. Each segment starts where the last one ended, the first at 0.": "Одна строка на сегмент: время его конца после старта двигателя (с), значение в конце ({u}) и форма: linear (линейная), cubic (кубическая), quintic (полином 5-й степени), harmonic (гармоническая) или cycloid (циклоидальная). Каждый сегмент начинается там, где закончился предыдущий, первый — с 0.",
  "Type one row per segment: end time, end value and shape, with the times increasing.": "Введите по строке на сегмент: время конца, значение в конце и форму; время должно возрастать.",
