  "Open triangle": "Незакрашенный треугольник",
  "Fillet the edges": "Скруглить кромки",
  "Edge fillet radius": "Радиус скругления кромок",
  "The gusset's edge fillet must be less than half its width.": "Радиус скругления кромок ребра должен быть меньше половины его ширины.",
  "Tab and Slot": "Шип и паз",
  "Tab-and-Slot": "Шип-и-паз",
  "Tab and slot: grow tabs out of a sheet edge through slots cut in the face they meet, with clearance, so parts locate for welding": "Шип и паз: вывести шипы из кромки листа сквозь пазы, вырезанные с зазором в грани, которую они встречают, чтобы детали фиксировались под сварку",
  "Pick a straight edge of the sheet for the tabs.": "Выберите прямую кромку листа для шипов.",
  "Pick the face the tabs go through.": "Выберите грань, сквозь которую проходят шипы.",
  "Tab edge picked": "Кромка шипов выбрана",
  "click a straight edge of the sheet for the tabs": "щёлкните прямую кромку листа для шипов",
  "Slot face picked": "Грань пазов выбрана",
  "click the face the tabs go through": "щёлкните грань, сквозь которую проходят шипы",
  "The tabs grow out of the edge in its face's plane and pass through the slot face, square to it; the face may belong to another body.": "Шипы выходят из кромки в плоскости её грани и проходят сквозь грань пазов перпендикулярно ей; грань может принадлежать другому телу.",
  "Tab length": "Длина шипа",
  "Tab height": "Высота шипа",
  "The height is how far a tab stands past the slot face.": "Высота — насколько шип выступает за грань пазов.",
  "Number of tabs": "Число шипов",
  "Fixed spacing": "Постоянный шаг",
  "Centre to centre, the group centred on the edge.": "От центра до центра, группа по центру кромки.",
  "Edge offset": "Отступ от концов кромки",
  "Equal spacing between the outer tabs, this far from the edge's ends.": "Равный шаг между крайними шипами, отстоящими на это расстояние от концов кромки.",
  "Round the slot corners": "Скруглить углы пазов",
  "Corner radius": "Радиус углов",
  "The slot is the tab's section grown by the clearance all round, as deep as the tab reaches.": "Паз — сечение шипа, увеличенное на зазор со всех сторон, глубиной до конца шипа.",
  "Use a whole number of tabs from 1 to 100.": "Укажите целое число шипов от 1 до 100.",
  "Tabs go on a straight edge.": "Шипы ставятся на прямую кромку.",
  "Pick the flat face the edge looks at, square to the tabs.": "Выберите плоскую грань напротив кромки, перпендикулярную шипам.",
  "Rip: cut a narrow gap along the inside corner edges of a thin-walled solid, so Insert Bends can unfold its walls": "Разрез: прорезать узкий зазор вдоль внутренних угловых рёбер тонкостенного тела, чтобы «Вставить сгибы» могли развернуть его стенки",
  "Make a thin-walled solid to rip first.": "Сначала создайте тонкостенное тело для разреза.",
  "Pick the corner edges to rip.": "Выберите угловые рёбра для разреза.",
  "Edges to rip": "Рёбра для разреза",
  "click the straight edges where two walls meet": "щёлкните прямые рёбра, где встречаются две стенки",
  "Both directions": "В обоих направлениях",
  "Along the first face": "Вдоль первой грани",
  "Along the second face": "Вдоль второй грани",
  "Rip gap": "Зазор разреза",
  "Pick a straight edge where two flat walls meet.": "Выберите прямое ребро, где встречаются две плоские стенки.",
  "Both directions cut the gap on the corner's bisector; one direction cuts it along one wall, so the other wall keeps the corner. One direction needs an inside corner edge.": "В обоих направлениях зазор режется по биссектрисе угла; в одном направлении — вдоль одной стенки, и угол остаётся у другой. Для одного направления нужно внутреннее угловое ребро.",
  "The rip gap must be more than zero.": "Зазор разреза должен быть больше нуля.",
  "A rip edge is gone; pick it again.": "Ребро разреза пропало; выберите его снова.",
  "Rip straight edges only.": "Разрезать можно только прямые рёбра.",
  "Rip edges between two flat faces.": "Разрезайте рёбра между двумя плоскими гранями.",
  "One-direction rips need an inside corner edge; pick the inside edge or rip both ways.": "Для разреза в одном направлении нужно внутреннее угловое ребро; выберите внутреннее ребро или режьте в обе стороны.",
  "There is no wall behind a rip edge.": "За ребром разреза нет стенки.",
  "Sheet Metal Properties": "Свойства листового металла",
  "Sheet metal properties: the cut-list values of the flat pattern (bounding box, thickness, cutting lengths, cut outs, bends, mass)": "Свойства листового металла: значения списка вырезов по развёртке (габаритный прямоугольник, толщина, длины реза, вырезы, сгибы, масса)",
  "Sheet metal properties": "Свойства листового металла",
