  "Bounding box width": "Ширина габаритного прямоугольника",
  "Sheet metal thickness": "Толщина листа",
  "Bounding box area": "Площадь габаритного прямоугольника",
  "Flat pattern area": "Площадь развёртки",
  "Cutting length - outer": "Длина реза — наружный контур",
  "Cutting length - inner": "Длина реза — внутренние контуры",
  "Cut outs": "Вырезы",
  "Bends": "Сгибы",
  "Measured on the flat pattern of the sheet; flatten the part to include cuts made by other features.": "Измерено по развёртке листа; разверните деталь, чтобы учесть вырезы других элементов.",
  "The slot face is behind the edge.": "Грань пазов находится позади кромки.",
