  "The bead runs this length from the start offset along each run of edges.": "Шов идёт на эту длину от смещения начала вдоль каждой цепочки кромок.",
  "The start offset must not be negative.": "Смещение начала не может быть отрицательным.",
  "The weld starts past the end of the edges.": "Шов начинается за концом кромок.",
  "Staggered": "В шахматном порядке",
  "Welds of this length every pitch, centre to centre, from the start of each run of edges. Staggered starts every other run half a pitch on.": "Швы этой длины через каждый шаг (между центрами) от начала каждой цепочки рёбер. В шахматном порядке каждая вторая цепочка начинается на полшага дальше.",
  "The weld length must be more than zero.": "Длина шва должна быть больше нуля.",
