  "Click a face of the other member: the first member stops at its side, the other runs on to the first one's far side.": "Щёлкните грань другого элемента: первый элемент упирается в его бок, другой продолжается до дальней стороны первого.",
  "Click a face of the other member: it stops at the first member's side, the first runs on to its far side.": "Щёлкните грань другого элемента: он упирается в бок первого элемента, первый продолжается до его дальней стороны.",
