  "Open the McMaster-Carr catalogue. Download a part's 3-D STEP file there and drop it on the assembly: it comes in with its part number and a link to buy it.": "Открыть каталог McMaster-Carr. Скачайте там 3-D STEP модель детали и перетащите её на сборку: она добавится с артикулом и ссылкой для покупки.",
  "{vendor} part {number}: the BOM lists it with a link to buy it.": "Деталь {vendor} {number}: в спецификации есть ссылка для покупки.",
  "Download a part's 3-D STEP file from {vendor} and drop it on the assembly.": "Скачайте 3-D STEP модель детали с {vendor} и перетащите её на сборку.",
  "Vendor": "Поставщик",
  "Buy at {vendor}": "Купить у {vendor}",
