  "Click two corners for the first side, then the width": "Щёлкните два угла первой стороны, затем ширину",
  "Click the centre, the middle of a side, then a corner": "Щёлкните центр, середину стороны, затем угол",
  "Click three corners; the fourth follows": "Щёлкните три угла; четвёртый получится сам",
  "Parabola": "Парабола",
