  "Equation curve": "Кривая по уравнению",
  "Equation driven curve": "Кривая, управляемая уравнением",
  "Parabola: focus, vertex, then the start and the end": "Парабола: фокус, вершина, затем начало и конец",
  "Conic: start, end, the top vertex, then a point that sets rho": "Коническое сечение: начало, конец, вершина касательных, затем точка, задающая rho",
  "Equation driven curve: y = f(x), or x(t) and y(t)": "Кривая по уравнению: y = f(x) или x(t) и y(t)",
  "Click the start, the end, the top vertex where the end tangents meet, then a point the conic passes through": "Щёлкните начало, конец, вершину, где сходятся касательные в концах, затем точку, через которую проходит кривая",
  "Click the focus, the vertex, then the start and the end": "Щёлкните фокус, вершину, затем начало и конец",
  "Type the equation and its range in the panel, then Add curve": "Введите уравнение и его диапазон на панели, затем «Добавить кривую»",
  "The top vertex is on the line between the ends.": "Вершина лежит на прямой между концами.",
  "Pick the ends on either side of the axis, away from each other.": "Укажите концы по разные стороны от оси, подальше друг от друга.",
  "Rho": "Параметр Rho",
  "Rho below 0.5 makes an ellipse, 0.5 a parabola, above 0.5 a hyperbola. Drag the ends or the top vertex to shape it.": "Rho меньше 0,5 даёт эллипс, 0,5 — параболу, больше 0,5 — гиперболу. Перетаскивайте концы или вершину, чтобы изменить форму.",
  "Explicit: y = f(x)": "Явная: y = f(x)",
