  "From t": "От t",
  "To t": "До t",
  "Lengths in millimetres, angles in radians; sin, cos, sqrt, ^ and pi work. The end points are fixed where the equation puts them.": "Длины в миллиметрах, углы в радианах; работают sin, cos, sqrt, ^ и pi. Конечные точки фиксируются там, где их задаёт уравнение.",
  "Add curve": "Добавить кривую",
