  "Tutorial finished: the bracket is done.": "Урок пройден: кронштейн готов.",
  "Start a sketch on the Top plane": "Начните эскиз на плоскости «Сверху»",
  "Click Sketch on the Sketch tab, then the Top (XY) plane.": "Нажмите «Эскиз» на вкладке «Эскиз», затем плоскость «Сверху (XY)».",
  "Draw the base rectangle": "Нарисуйте прямоугольник основания",
  "Pick Rectangle, click the origin, then click again up and to the right.": "Выберите «Прямоугольник», щёлкните в начале координат, затем ещё раз выше и правее.",
  "Give it sizes: 80 × 50 mm": "Задайте размеры: 80 × 50 мм",
  "Pick Dimension, click a side, click beside it and type the size. Do the same for the other side; the sketch turns fully defined.": "Выберите «Размер», щёлкните сторону, щёлкните рядом и введите значение. Повторите для другой стороны: эскиз станет полностью определённым.",
  "Extrude the base 6 mm": "Вытяните основание на 6 мм",
  "Exit the sketch, click Extrude on the Features tab, type 6 and confirm with ✓.": "Выйдите из эскиза, нажмите «Вытягивание» на вкладке «Элементы», введите 6 и подтвердите ✓.",
  "Sketch the wall on the base": "Эскиз стенки на основании",
  "Click the top face of the base, then Sketch. Draw a 6 mm wide rectangle along one long side.": "Щёлкните верхнюю грань основания, затем «Эскиз». Нарисуйте прямоугольник шириной 6 мм вдоль длинной стороны.",
  "Extrude the wall 40 mm": "Вытяните стенку на 40 мм",
  "Exit the sketch and extrude it 40 mm upwards: the bracket has its L shape.": "Выйдите из эскиза и вытяните его на 40 мм вверх: кронштейн получил Г-образную форму.",
  "Round the inside corner": "Скруглите внутренний угол",
  "Click Fillet, pick the edge where the wall meets the base, type 5 and confirm.": "Нажмите «Скругление», выберите ребро между стенкой и основанием, введите 5 и подтвердите.",
  "Add a mounting hole": "Добавьте крепёжное отверстие",
  "Click Hole, click the base where the hole goes, choose a size and confirm. A circle sketch removed with Cut works too.": "Нажмите «Отверстие», щёлкните основание в месте отверстия, выберите размер и подтвердите. Подойдёт и окружность, вырезанная командой «Вырез».",
  "Break the sharp edges": "Притупите острые кромки",
