  "First line: bend angles in degrees. Each further line: an inside radius in mm, then a value per angle (allowances and deductions in mm). Values in between are interpolated; outside the table the nearest row or column is used.": "Первая строка: углы сгиба в градусах. Каждая следующая: внутренний радиус в мм, затем значение для каждого угла (допуски и вычеты в мм). Промежуточные значения интерполируются; за пределами таблицы берётся ближайшая строка или столбец.",
